:root {
  --tag-bg: #f2e8d5;
  --tag-border: #8b5e2e;
  --tag-header-bg: #8b5e2e;
  --tag-title-color: #f2e8d5;
  --tag-icon-bg: #c9883a;
  --fuel-name-color: #4a2e0e;
  --fuel-note-color: #7a5230;
  --footer-bg: #ddd0b3;
  --footer-text: #5a3c14;
  --divider: #b8945a;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

.fuel-tag {
  background-color: var(--tag-bg);
  border: 3px solid var(--tag-border);
  border-radius: 10px;
  width: 240px;
  overflow: hidden;
}

.tag-header {
  background-color: var(--tag-header-bg);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
}

.tag-icon {
  background-color: var(--tag-icon-bg);
  border-radius: 6px;
  font-size: 20px;
  padding: 4px 6px;
  line-height: 1;
}

.tag-title {
  color: var(--tag-title-color);
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin: 0;
}

.tag-body {
  padding: 14px 16px 10px;
  border-bottom: 2px dashed var(--divider);
}

.fuel-name {
  color: var(--fuel-name-color);
  font-size: 15px;
  font-weight: 700;
  margin: 0 0 4px;
}

.fuel-note {
  color: var(--fuel-note-color);
  font-size: 12px;
  font-style: italic;
  margin: 0;
}

.tag-footer {
  background-color: var(--footer-bg);
  display: flex;
  justify-content: space-between;
  padding: 8px 16px;
}

.tag-lot,
.tag-date {
  color: var(--footer-text);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
